import{K as r,a as l,c as n,b as a,k as i,q as s,ac as c}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"OneNote 搜索、标签、模板与知识整理","description":"将零散笔记整理成可复用的知识库，使用一致标题、标签、页面链接和会议模板，检查搜索范围、版本恢复和导出边界。","frontmatter":{"title":"OneNote 搜索、标签、模板与知识整理","description":"将零散笔记整理成可复用的知识库，使用一致标题、标签、页面链接和会议模板，检查搜索范围、版本恢复和导出边界。","showdocs":{"topics":[{"id":"office","title":"Office","link":"/topics/office/"}],"kind":"使用指南","scope":"general","audience":"general","group":"工程与工具","seriesTitle":"Office · OneNote 笔记管理","summary":"将零散笔记整理成可复用的知识库，使用一致标题、标签、页面链接和会议模板，检查搜索范围、版本恢复和导出边界。","status":"active","related":[{"title":"Excel 实战：建立可刷新、可核对的月报","link":"/tools/office/excel/project","kind":"实践案例","scope":"general","audience":"general"},{"title":"Office 常见问题排查与交付检查表","link":"/tools/office/collaboration/troubleshooting","kind":"故障排查","scope":"general","audience":"general"},{"title":"Office 常用快捷键、选择与粘贴技巧","link":"/tools/office/start/shortcuts","kind":"参考资料","scope":"general","audience":"general"},{"title":"Office 综合实战：从数据到报告、演示和会议","link":"/tools/office/collaboration/workflow","kind":"实践案例","scope":"general","audience":"general"},{"title":"Word 实战：制作可维护的项目报告","link":"/tools/office/word/report","kind":"实践案例","scope":"general","audience":"general"}],"prev":{"text":"OneNote 笔记本、分区与会议记录","link":"/tools/office/onenote/notes"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"OneNote 笔记本、分区与会议记录","link":"/tools/office/onenote/notes"},"next":false},"headers":[],"relativePath":"tools/office/onenote/knowledge.md","filePath":"tools/office/onenote/knowledge.md"}'),h={name:"tools/office/onenote/knowledge.md"},k=Object.assign(h,{setup(d){const t={path:"/tools/office/onenote/knowledge",app:"OneNote",title:"把会议记录变成能复用的操作说明",steps:[{tab:"插入",command:"表格",setting:"列：步骤 / 检查结果 / 异常处理",anchor:"walkthrough-1"},{tab:"开始",command:"查找标记",setting:"标记：疑问 / 待办；明确搜索范围",anchor:"walkthrough-2"},{tab:"插入",command:"链接",setting:"链接回原会议页与源文件；重新检索",anchor:"walkthrough-3"}]};return(p,e)=>{const o=r("OfficeGuide");return l(),n("div",null,[e[0]||(e[0]=a("h1",{id:"onenote-搜索、标签、模板与知识整理",tabindex:"-1"},[i("OneNote 搜索、标签、模板与知识整理 "),a("a",{class:"header-anchor",href:"#onenote-搜索、标签、模板与知识整理","aria-label":'Permalink to "OneNote 搜索、标签、模板与知识整理"'},"​")],-1)),e[1]||(e[1]=a("p",null,"笔记的价值在于以后能找到并再次使用。整理时围绕实际任务形成说明，不只把网页和截图堆在一起。本篇把月报项目中的过程记录整理成可复用的操作说明。",-1)),s(o,{guide:t}),e[2]||(e[2]=c('<h2 id="titles" tabindex="-1">建立可检索标题 <a class="header-anchor" href="#titles" aria-label="Permalink to &quot;建立可检索标题 {#titles}&quot;">​</a></h2><p>标题同时写主题和目的，例如“Excel 月报：刷新后金额不一致的排查步骤”，比“问题”“随便记一下”更容易被找到。页面开头记录适用版本、最后核对日期和对应文件位置，旧结论不应被误当作当前规则。</p><p>同一主题可保留入口页面，列出基础操作、常见问题、参考来源和相关项目记录。通过页面链接连接内容，减少重复复制。来源更新时，在说明中记录变化，而不是默默留下几份互相矛盾的摘录。</p><h2 id="tags" tabindex="-1">标签与搜索范围 <a class="header-anchor" href="#tags" aria-label="Permalink to &quot;标签与搜索范围 {#tags}&quot;">​</a></h2><p>标签可表示待办、重要、疑问等状态。保持数量少且含义明确，例如“疑问”表示仍需确认，不用于强调所有段落。按版本提供的标签搜索或摘要功能检查未完成项，定期清理已过期事项。</p><p>搜索无结果时先确认是当前页、分区、笔记本还是所有可用笔记本。图像文字识别、手写和音频搜索的能力受客户端、语言和处理状态影响；重要信息应同时写为可检索文本，不把检索能力全部寄托在截图 OCR 上。</p><h2 id="template" tabindex="-1">做一个可复制的页面框架 <a class="header-anchor" href="#template" aria-label="Permalink to &quot;做一个可复制的页面框架 {#template}&quot;">​</a></h2><p>创建页面 <code>会议模板</code>，固定包含以下小节：会议目标、材料、讨论、决策、行动项、下次检查日期。支持页面模板的桌面版本可以保存为模板；其他版本可复制该页面再修改标题，避免把某个菜单当作全平台通用能力。</p><p>模板中的示例姓名和日期应明显标为占位，复制后立即填写。不要把上次会议的已完成事项留在模板里，否则新会议记录会混入旧内容。</p><h2 id="distill" tabindex="-1">从过程笔记提炼说明 <a class="header-anchor" href="#distill" aria-label="Permalink to &quot;从过程笔记提炼说明 {#distill}&quot;">​</a></h2><p>会议页写“刷新后少了两行”只是现象。整理为操作说明时补充输入条件、步骤、预期结果、异常检查和关联文件。例如月报刷新流程可写：更新源文件 → 查看查询错误行 → 刷新输出 → 刷新透视表 → 核对金额 → 导出。</p><p>对外部资料，保留链接、标题和阅读日期，用自己的话写它解决的问题。引用某个片段时注明上下文，不把别人的完整文档复制进公共笔记本。项目结束后区分仍然有效的通用规则与仅适用于那次会议的决定。</p><h2 id="recover" tabindex="-1">恢复、导出与归档 <a class="header-anchor" href="#recover" aria-label="Permalink to &quot;恢复、导出与归档 {#recover}&quot;">​</a></h2><p>不同客户端可能提供页面版本、已删除笔记或笔记本回收站等入口，保留期限和范围受服务与组织设置影响。误删后先停止继续清理，检查对应恢复入口，找到后验证页面和附件；不要依赖“应该一直能恢复”。</p><p>需要归档或分享时，按实际客户端可用的导出/打印功能选择 PDF 等格式，检查长页面是否被切断、表格是否过宽、链接是否可用。导出固定页面不等于备份了整个笔记本的所有历史和附件。</p><h2 id="practice" tabindex="-1">练习与验收 <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;练习与验收 {#practice}&quot;">​</a></h2><p>从前一篇会议记录提炼一页“月报刷新说明”，保留原会议链接和数据口径。关闭当前页后，通过关键词在合理范围内重新找到它；找不到时调整标题和文本。让另一位有权限的读者仅依据此页完成流程，记录需要补充的说明。</p><p>参考：<a href="https://support.microsoft.com/en-us/onenote" target="_blank" rel="noopener noreferrer">OneNote 帮助与学习</a>。</p><h2 id="walkthrough" tabindex="-1">图示跟做：把会议记录变成能复用的操作说明 <a class="header-anchor" href="#walkthrough" aria-label="Permalink to &quot;图示跟做：把会议记录变成能复用的操作说明 {#walkthrough}&quot;">​</a></h2><p>按上方图示切换三个关键步骤；下面保留完整操作和检查结果，便于跟做与回查。请先使用练习副本。</p><h3 id="walkthrough-1" tabindex="-1">第 1 步：提炼一页完整流程 <a class="header-anchor" href="#walkthrough-1" aria-label="Permalink to &quot;第 1 步：提炼一页完整流程 {#walkthrough-1}&quot;">​</a></h3><p><strong>定位：插入 → 表格。</strong></p><p>新建“Excel 月报刷新说明”页面，在顶部写适用文件、版本和核对日期。插入三列表格，把更新源表、刷新查询、刷新透视表、核对金额、导出写成独立行。每步都写判断完成的结果，而不是只把会议原文复制过来。</p><h3 id="walkthrough-2" tabindex="-1">第 2 步：让未解决的问题可见 <a class="header-anchor" href="#walkthrough-2" aria-label="Permalink to &quot;第 2 步：让未解决的问题可见 {#walkthrough-2}&quot;">​</a></h3><p><strong>定位：开始 → 查找标记。</strong></p><p>给仍不确定的来源路径加疑问标记，给待核对金额加待办标记。支持查找标记的桌面版可生成标签摘要，并核对当前搜索范围。其他客户端用关键词搜索作为替代；不要只把关键信息写进截图，图像识别未完成时可能查不到。</p><h3 id="walkthrough-3" tabindex="-1">第 3 步：建立来源和复用入口 <a class="header-anchor" href="#walkthrough-3" aria-label="Permalink to &quot;第 3 步：建立来源和复用入口 {#walkthrough-3}&quot;">​</a></h3><p><strong>定位：插入 → 链接。</strong></p><p>复制原会议页面链接，在说明末尾插入“决定来源”，再补受权限保护的源文件链接。关闭页面，通过“月报 刷新”重新查找，核对标题足够具体。后续规则变化时更新操作说明并注明日期，历史会议记录保留当时决定，不应悄悄改成新的事实。</p><h3 id="walkthrough-check" tabindex="-1">没有得到预期结果时 <a class="header-anchor" href="#walkthrough-check" aria-label="Permalink to &quot;没有得到预期结果时 {#walkthrough-check}&quot;">​</a></h3><p>模板复制后立即替换日期、人员和材料位置。包含旧负责人或旧数值的模板会把历史内容带入新会议，比没有模板更难排查。</p>',31))])}}});export{u as __pageData,k as default};
